    const ctrlK = (ev.ctrlKey || ev.metaKey) && !ev.altKey && !ev.shiftKey && ev.key.toLowerCase() === 'k';
    const barra = ev.key === '/' && !ev.ctrlKey && !ev.metaKey && !ev.altKey && !escribiendo(ev.target);
